'use strict'

// Echo Lake Foods adapter for the shared multi-customer order agent.
// Added 2026-10-16 as the fifth customer (after Grassland, Richelieu,
// Pedone Pinsa, Thomas Foods International).
//
// WHAT THESE ORDERS ARE: an "Order Verification" PDF generated by Echo
// Lake's own ERP system ("Emerald"), one per email, sender domain
// echolakefoods.com. CSW ships OUT of Kenosha (project ECHOL5, project_id
// 128 — Echo Lake also has separate Madison/Caledonia projects, ECHOL1/
// ECHOL9, not touched by this adapter) on Echo Lake's behalf to a THIRD
// PARTY — the PDF's own "Bill To"/"Ship To" is the actual end customer
// (e.g. Holiday Stationstores LLC), not Echo Lake itself; "LOAD From: CSW
// ... Pleasant Prairie" on the PDF is what confirms the Kenosha project
// and direction. Confirmed via real Datex order history: genuinely
// outbound Sales Orders (order_class_id 2, "SO"), same class every
// customer in this agent uses.
//
// STRUCTURALLY THE SIMPLEST CUSTOMER SO FAR, same shape as Pedone: direct
// Part # -> material lookup, the PDF's printed "Qty" (cases) pushed
// verbatim as the quantity — no lot concept at all (every real historical
// line for this project has lot_id/storage_lot null), no pallet/tote
// conversion needed. `packaged_id` fixed at 3 ("CS"), confirmed across
// 607 real historical lines, zero exceptions. Confirmed via an exact
// real-order match: order 814772 (PO003600-WH3750141) has the IDENTICAL
// two materials and quantities (MF5500BP: 1152, MF3052: 924) as the
// sample order checked 2026-10-16 (438650) — this Holiday Stationstores
// line item is evidently a recurring, unchanging order.
//
// UNLIKE PEDONE, THIS DOCUMENT HAS A REAL PRINTED GRAND TOTAL — the
// bottom "Total" row (total cases, total pallets) gives a genuine
// structural self-consistency check before ever touching Datex, same
// spirit as Grassland's/Richelieu's printed-total checks. See
// validateEchoLakeTotals in the Edge Function.
//
// HEADER FIELD MAPPING — a fourth distinct convention, confirmed against
// several real historical orders: `lookup_code`/`owner_reference` = the
// Echo Lake "Order #" (e.g. "438650"); `vendor_reference` = the PDF's own
// "Bill To PO" field (e.g. "PO003710-WH3750141") — confirmed directly: a
// real historical order (814772) has vendor_reference stored as
// "PO003600-WH3750141", exactly matching this field's format (the PDF
// prints a space around the dash; Datex's stored value has none — the
// adapter normalizes this by stripping spaces around the dash before
// pushing, to match the confirmed-real format rather than guessing
// Datex accepts the spaced version too).
//
// `carrier_id` LEFT NULL, same situation as Thomas Foods: real historical
// orders for this project DO have a real, varying carrier set, but this
// PDF's own "Deliver Via"/"Carrier Po" fields are blank — carrier is
// presumably arranged separately, not present on the order-verification
// document itself.
//
// KNOWN OPEN QUESTION, not yet resolved: this PDF is explicitly marked
// "Revised" — meaning Echo Lake can and does resend a PDF for the SAME
// order number with updated/corrected lines. The current dedupe check
// (by order number) would treat a genuine revision as "already processed,
// skip" rather than updating the existing order — this needs a real
// decision (re-open and re-push, create a change order, or something
// else) before a true revision scenario is tested for real.

const { runMotherDuckQuery } = require('../order-agent-common.cjs')

const ECHOLAKE_PROJECT_ID = 128 // ECHOL5 — Echo Lake Foods Inc - Kenosha
const KENOSHA_WAREHOUSE_ID = 5 // CSW-Kenosha
const ECHOLAKE_ORDER_CLASS_ID = 2 // "SO" Sales Order — same class as every other customer here
const ECHOLAKE_PACKAGING_ID = 3 // "CS" — confirmed fixed across 607 real historical lines, zero exceptions

// Looks up every Part # printed on one PDF, scoped to the Echo Lake
// Kenosha project only. TRIM() on both sides guards against the same
// stray-whitespace issue confirmed on other customers' codes (2026-10-14).
async function fetchMaterials(partNumbers) {
  if (!partNumbers.length) return new Map()
  const inList = partNumbers.map((s) => `'${s.trim().replace(/'/g, "''")}'`).join(',')
  const rows = await runMotherDuckQuery(`
    SELECT material_id AS material_id, TRIM(lookup_code) AS part_number
    FROM production_db.silver.datex_slv_materials
    WHERE project_id = ${ECHOLAKE_PROJECT_ID}
      AND TRIM(lookup_code) IN (${inList})
  `)
  const map = new Map()
  for (const r of rows) map.set(r.part_number, r)
  return map
}

async function resolveOrderLines(parsed) {
  const lines = parsed.lines || []
  if (lines.length === 0) {
    return { ok: false, flagReason: 'No line items were extracted from this Order Verification PDF.' }
  }

  const partNumbers = [...new Set(lines.map((l) => (l.part_number || '').trim()))]
  const materialsByPart = await fetchMaterials(partNumbers)

  const resolvedLines = []
  const unresolvedParts = []

  for (const line of lines) {
    const material = materialsByPart.get((line.part_number || '').trim())
    if (!material) {
      unresolvedParts.push(line.part_number)
      resolvedLines.push({ ...line, line_status: 'missing_lp' })
      continue
    }
    resolvedLines.push({
      ...line,
      line_status: 'resolved',
      item_count: line.case_quantity,
      resolved_material_id: material.material_id,
      resolved_material_code: material.part_number,
      resolved_packaging_id: ECHOLAKE_PACKAGING_ID,
    })
  }

  const anyUnresolved = resolvedLines.some((l) => l.line_status !== 'resolved')
  if (anyUnresolved) {
    return {
      ok: false,
      resolvedLines,
      flagReason: `Could not resolve Part #(s) to a material in project ECHOL5: ${[...new Set(unresolvedParts)].join(', ')}.`,
    }
  }

  // The PDF's own printed grand total was already checked structurally in
  // the Edge Function (no external data needed for that) — nothing
  // further to validate here beyond resolving every line to a real
  // material, same as Pedone.
  return { ok: true, resolvedLines }
}

function buildOrderHeader(parsed) {
  // Normalize "PO003710 - WH3750141" -> "PO003710-WH3750141" to match the
  // confirmed real stored format (see file header note) rather than
  // trusting Datex to accept the spaced version too.
  const vendorRef = parsed.bill_to_po ? parsed.bill_to_po.replace(/\s*-\s*/g, '-').trim() : null
  return {
    project_id: ECHOLAKE_PROJECT_ID,
    warehouse_id: KENOSHA_WAREHOUSE_ID,
    order_class_id: ECHOLAKE_ORDER_CLASS_ID,
    lookup_code: parsed.order_number || null,
    owner_reference: parsed.order_number || null,
    vendor_reference: vendorRef,
    order_notes: null,
    carrier_id: null, // not on the PDF — see file header note
    expected_date: parsed.ship_date || null,
    shipping_address: {
      name: parsed.ship_to?.name || null,
      line1: parsed.ship_to?.line1 || null,
      line2: parsed.ship_to?.line2 || null,
      city: parsed.ship_to?.city || null,
      state: parsed.ship_to?.state || null,
      postal_code: parsed.ship_to?.zip || null,
      country: 'US',
    },
  }
}

function buildLinePayload(line, ctx) {
  return {
    order_id: ctx.order_id,
    shipment_id: ctx.shipment_id,
    line_number: ctx.line_number,
    material_id: line.resolved_material_id,
    expected_quantity: line.item_count,
    actual_quantity: line.item_count,
    packaging_id: line.resolved_packaging_id,
  }
}

module.exports = {
  customerCode: 'echolake',
  domains: ['echolakefoods.com'],
  resolveOrderLines,
  buildOrderHeader,
  buildLinePayload,
  ECHOLAKE_PROJECT_ID,
  KENOSHA_WAREHOUSE_ID,
}
